reply:
{
  "title": "Civilian Access to Intelligence-System Photography",
  "setting": "United States, after the 1973 abolition of the Office of the President’s Science Adviser, in the Commission’s review of civilian use of aerial intelligence photography.",
  "decider": "The Commission",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The Commission",
  "agent_role": "advise",
  "situation": "Civilian agencies use aerial intelligence photography for projects including mapping, disaster assessment, pipeline route surveys, forest inventories, and crop-blight detection. The Director of Central Intelligence has entered agreements allowing several federal agencies access to classified overhead photography. Earlier arrangements provided photography on civilian-agency committee request, subject to no interference with intelligence needs and no significant cost increase. The civilian steering committee ceased to exist in 1973, while efforts to establish a new committee were underway. A concern is that information from a civilian use could potentially support an environmental criminal action.",
  "question": "What should the Commission recommend the Director of Central Intelligence do about civilian agencies’ access to intelligence-system photography and the conditions governing that access?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "confirmed",
      "fact": "A steering committee for civilian use of aerial photography was established in 1967.",
      "spans": [
        "src:e72ab1a2ab4b#p6.4"
      ]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The steering committee was intended to serve as an interface through which the intelligence community could assure the public that it did not select or determine the end use of domestic aerial photographs.",
      "spans": [
        "src:e72ab1a2ab4b#p6.4"
      ]
    },
    {
      "id": "F3",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The Director of Central Intelligence agreed to provide photography on steering committee requests, provided there was no interference with intelligence needs and no significant cost increase.",
      "spans": [
        "src:e72ab1a2ab4b#p6.4"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Civilian uses included mapping, disaster assessment, pipeline route surveys, forest inventories, snow-cover assessment, crop-blight detection, and limited equipment testing and performance evaluation.",
      "spans": [
        "src:e72ab1a2ab4b#p6.5"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "confirmed",
      "fact": "In 1973, the Office of the President’s Science Adviser was abolished and the special steering committee controlling civilian use ceased to exist; efforts were underway to establish a new committee.",
      "spans": [
        "src:e72ab1a2ab4b#p6.6"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The Director of Central Intelligence had entered agreements with several federal agencies allowing them access to classified overhead photography.",
      "spans": [
        "src:e72ab1a2ab4b#p6.6",
        "src:e72ab1a2ab4b#p7.1"
      ]
    },
    {
      "id": "F7",
      "kind": "capability",
      "status": "confirmed",
      "fact": "The CIA engineered and developed most of the operational aerial photography systems, but was no longer responsible for their operational aspects.",
      "spans": [
        "src:e72ab1a2ab4b#p6.6",
        "src:e72ab1a2ab4b#p6.7"
      ]
    },
    {
      "id": "F8",
      "kind": "intelligence",
      "status": "assessed",
      "fact": "Operating a single aerial photography program was considered economical and supported use of the photographs for appropriate civilian purposes.",
      "spans": [
        "src:e72ab1a2ab4b#p7.2"
      ]
    },
    {
      "id": "F9",
      "kind": "intelligence",
      "status": "assessed",
      "fact": "At least one present use was considered arguably law-enforcement in nature, and information from it could potentially support an environmental criminal action.",
      "spans": [
        "src:e72ab1a2ab4b#p7.3"
      ]
    },
    {
      "id": "F10",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The National Security Act of 1947 prohibited the CIA from engaging in law-enforcement activities.",
      "spans": [
        "src:e72ab1a2ab4b#p7.3"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The Commission recommends that the Director permit civilian agencies to use the photography on request, subject to no intelligence interference or significant cost increase.",
      "move": "act",
      "disposition": "permit",
      "irreversible": false
    },
    "O2": {
      "do": "The Commission recommends that the Director prohibit civilian agencies from using the photography and end existing agency access agreements.",
      "move": "act",
      "disposition": "prohibit",
      "irreversible": false
    },
    "O3": {
      "do": "The Commission recommends that the Director permit civilian access through a reestablished civilian committee under the existing operational and cost conditions.",
      "move": "partial",
      "disposition": "permit",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O3",
  "authored_options": [
    "O1",
    "O2"
  ],
  "no_opposite_reason": "",
  "basis_statement": "The Commission’s recommendation to reestablish a civilian agency committee endorses civilian access under committee oversight."
}
